create table public.transaction (
    "id" bigint generated by default as identity not null,
    "hash" text not null unique,
    "portfolio_id" bigint not null references public.portfolio("id") on delete cascade,
    -- "asset_id" bigint not null references public.asset("id") on delete cascade,
    "asset" text not null,
    "fee" numeric null default 0 check (fee >= 0),
    "amount" numeric null default 0 check (amount >= 0),
    "time" timestamp with time zone,
    "type" text not null check (type in ('buy', 'sell', 'withdrawal', 'deposit')),
    "created_at" timestamp with time zone default current_timestamp,
    constraint transaction_pkey primary key (id)
);
