--   |_||_|  \__,_|_| |_|___/\__,_|\___|\__|_|\___/|_| |_| |_|   \___/|_|_|\___|_|\___||___/
alter table "public"."transaction" enable row level security;
revoke
update,
    delete,
    insert on table "public"."transaction"
from anon,
    authenticated;
create policy "Allow users to view transactions for their portfolios" on "public"."transaction" as permissive for
select to authenticated using (
        exists (
            select 1
            from public.portfolio
            where portfolio.id = transaction.portfolio_id
                and portfolio.user_id = auth.uid()
        )
    );